#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/cli/tasks/func-backup.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# USAGE arg "<folder>" help="Folder to backup" required

import os
import subprocess
import sys
import time

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def run(*cmd):
  """Run the command. When it fails, stop the task with its code, as set -e
  does. A missing command gives 127, as in the shell."""
  sys.stdout.flush()
  try:
    rc = subprocess.run(cmd, check=False).returncode
  except FileNotFoundError:
    print(f"{cmd[0]}: command not found", file=sys.stderr, flush=True)
    sys.exit(127)
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def main():
  # Generate timestamp for unique filename
  stamp = time.strftime("%Y%m%d-%H%M%S")

  # Get absolute path and extract components
  name = os.environ.get("usage_folder", "")
  if not name:
    print("usage_folder: parameter null or not set", file=sys.stderr, flush=True)
    sys.exit(1)
  folder = f"{os.environ.get('MISE_ORIGINAL_CWD', '')}/{name}"
  if not os.path.isdir(folder):
    print(f"cd: {folder}: No such file or directory", file=sys.stderr, flush=True)
    sys.exit(1)
  fullpath = os.path.realpath(folder)
  parent, _, basename = fullpath.rpartition("/")  # The parent directory and the filename/dirname

  # Construct timestamped backup filename
  filename = f"{parent}/{basename}-{stamp}.zip"

  # Display progress message with colored output
  helpers.print_header(f"Backing up from {fullpath} to {filename} ...")

  # Create recursive zip archive
  run("zip", "--recurse-paths", filename, fullpath, "-x", "*/.git/*", "-x", "*/node_modules/*")

  helpers.print_success(f"Backup completed: {filename}")


if __name__ == "__main__":
  main()
